import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { Group } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const root = new ctx.THREE.Group();

  // Geometry
  const geometry = new ctx.THREE.PlaneGeometry(1, 0.4);

  // Material
  const material = new MeshStandardNodeMaterial();
  material.color = new ctx.THREE.Color('#0b0b10'); // surface
  material.metalness = 0.0;
  material.roughness = 0.8;
  material.emissive = new ctx.THREE.Color('#ff2a38'); // accent edge
  material.emissiveIntensity = 0.2;

  // Load texture asynchronously
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // Mesh
  const mesh = new ctx.THREE.Mesh(geometry, material);
  root.add(mesh);

  // Interaction handlers
  let hoverTL = null;

  function hoverEnter() {
    if (hoverTL) hoverTL.kill();
    hoverTL = gsap.timeline();
    hoverTL.to(mesh.position, {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  function hoverLeave() {
    if (hoverTL) hoverTL.kill();
    hoverTL = gsap.timeline();
    hoverTL.to(mesh.position, {
      y: mesh.position.y - 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  function onClick() {
    ctx.emit('hub-collection.select', {});
  }

  root.userData.handlers = {
    hover: { enter: hoverEnter, leave: hoverLeave },
    click: onClick,
  };

  // Cleanup
  root.userData.cleanup = () => {
    if (hoverTL) hoverTL.kill();
    material.dispose();
    geometry.dispose();
    if (material.map) material.map.dispose();
  };

  return root;
}
